From c3d503d65a4426666cddbbb4a8bc485717991409 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 15:41:37 +0100
Subject: [PATCH] session-restore: restore windows on the activities they were
 on

The fallback session save only stored which apps were running, so after
logging in every relaunched app opened on the current activity. It now
saves the activities of each app's window and moves the new one there.

BUG: 348047
---
 startkde/session-restore/CMakeLists.txt |  3 ++
 startkde/session-restore/restore.cpp    | 59 ++++++++++++++++++++++++-
 startkde/session-restore/save.cpp       |  1 +
 3 files changed, 61 insertions(+), 2 deletions(-)

diff --git a/startkde/session-restore/CMakeLists.txt b/startkde/session-restore/CMakeLists.txt
index d454251345..3962be0e9a 100644
--- a/startkde/session-restore/CMakeLists.txt
+++ b/startkde/session-restore/CMakeLists.txt
@@ -29,6 +29,9 @@ target_link_libraries( plasma-fallback-session-restore
     KF6::KIOGui
     KF6::ConfigCore
     KF6::ConfigGui
+    PW::LibTaskManager
+    Qt6::GuiPrivate
+    Wayland::Client
 )

 install(TARGETS plasma-fallback-session-restore DESTINATION ${KDE_INSTALL_FULL_LIBEXECDIR})
diff --git a/startkde/session-restore/restore.cpp b/startkde/session-restore/restore.cpp
index d73b83831e..145be51929 100644
--- a/startkde/session-restore/restore.cpp
+++ b/startkde/session-restore/restore.cpp
@@ -5,8 +5,19 @@
 SPDX-License-Identifier: LGPL-2.1-or-later
 */

+#include <chrono>
+
 #include <QDir>
 #include <QGuiApplication>
+#include <QTimer>
+
+#include <qpa/qplatformnativeinterface.h>
+
+#include <wayland-client-core.h>
+
+#include <abstracttasksmodel.h>
+#include <activityinfo.h>
+#include <windowtasksmodel.h>

 #include <KApplicationTrader>
 #include <KConfigGroup>
@@ -19,6 +30,7 @@ SPDX-License-Identifier: LGPL-2.1-or-later
 #include "smserversettings.h"

 using namespace Qt::StringLiterals;
+using namespace std::chrono_literals;

 int main(int argc, char *argv[])
 {
@@ -37,6 +49,43 @@ int main(int argc, char *argv[])
     QList<KJob *> jobs;
     QEventLoop e;

+    TaskManager::WindowTasksModel tasksModel(&a);
+    TaskManager::ActivityInfo activityInfo(&a);
+
+    auto native = qGuiApp->platformNativeInterface();
+    auto display = static_cast<struct ::wl_display *>(native->nativeResourceForIntegration("wl_display"));
+    if (display) {
+        // fetch all window IDs
+        wl_display_roundtrip(display);
+        // fetch all window properties
+        wl_display_roundtrip(display);
+    }
+
+    // Activities the first window of each launched app was on when the session was saved
+    QHash<QString, QStringList> pendingActivities;
+    QObject::connect(&tasksModel, &QAbstractItemModel::rowsInserted, &e, [&](const QModelIndex &parent, int first, int last) {
+        for (int row = first; row <= last; ++row) {
+            const QModelIndex index = tasksModel.index(row, 0, parent);
+            const auto it = pendingActivities.constFind(tasksModel.data(index, TaskManager::AbstractTasksModel::StorageId).toString());
+            if (it == pendingActivities.constEnd()) {
+                continue;
+            }
+            QStringList activities = it.value();
+            const QStringList runningActivities = activityInfo.runningActivities();
+            activities.removeIf([&runningActivities](const QString &activity) {
+                return !runningActivities.contains(activity);
+            });
+            // An empty list means all activities, don't turn a window on removed activities into that
+            if (activities.isEmpty() == it.value().isEmpty()) {
+                tasksModel.requestActivities(index, activities);
+            }
+            pendingActivities.erase(it);
+        }
+        if (jobs.isEmpty() && pendingActivities.isEmpty()) {
+            e.quit();
+        }
+    });
+
     // Make a list of all autostart .desktop files for subsequent filtering
     QSet<QString> autoStartFiles;
     const QStringList dirs = QStandardPaths::locateAll(QStandardPaths::GenericConfigLocation, QStringLiteral("autostart"), QStandardPaths::LocateDirectory);
@@ -100,9 +149,13 @@ int main(int argc, char *argv[])
         qCDebug(FALLBACK_SESSION_RESTORE) << "launching " << service->name();
         auto job = new KIO::ApplicationLauncherJob(service);

-        QObject::connect(job, &KJob::finished, &e, [job, &jobs, &e]() {
+        if (config->group(groupName).hasKey("activities")) {
+            pendingActivities.insert(appId, config->group(groupName).readEntry("activities", QStringList()));
+        }
+
+        QObject::connect(job, &KJob::finished, &e, [job, &jobs, &e, &pendingActivities]() {
             jobs.removeOne(job);
-            if (jobs.isEmpty()) {
+            if (jobs.isEmpty() && pendingActivities.isEmpty()) {
                 e.quit();
             }
         });
@@ -110,6 +163,8 @@ int main(int argc, char *argv[])
         job->start();
     }
     if (!jobs.isEmpty()) {
+        // Give the launched apps some time to show their windows
+        QTimer::singleShot(30s, &e, &QEventLoop::quit);
         e.exec();
     }

diff --git a/startkde/session-restore/save.cpp b/startkde/session-restore/save.cpp
index 7cd20f4cf0..f99cd1bb8f 100644
--- a/startkde/session-restore/save.cpp
+++ b/startkde/session-restore/save.cpp
@@ -83,6 +83,7 @@ int main(int argc, char *argv[])
         auto group = config->group(QString::number(i));
         qCDebug(FALLBACK_SESSION_RESTORE) << "Saving" << group.name() << appId;
         group.writeEntry("appId", appId);
+        group.writeEntry("activities", tasksModel.data(index, TaskManager::AbstractTasksModel::Activities).toStringList());
         seenAppIds.insert(appId);
     }

